alter table public.service_catalog
  add column if not exists intake_heading text,
  add column if not exists intake_intro text,
  add column if not exists subject_placeholder text,
  add column if not exists intake_notice text,
  add column if not exists document_checklist jsonb not null default '[]'::jsonb;

update public.service_catalog set
  intake_heading = 'Tell us about your real estate goal.',
  intake_intro = 'The questions below change based on whether you are buying, selling, or searching for residential or commercial space.',
  subject_placeholder = 'Example: Two-bedroom rental search in Brooklyn',
  intake_notice = 'Do not enter Social Security numbers, bank account numbers, or payment-card information here. LIW will request sensitive documents through the secure portal only when needed.',
  document_checklist = $liw$["Government-issued photo identification","Proof of income or pre-approval letter, when applicable","Housing-program documents, when applicable","Property details or listing documents for sellers"]$liw$::jsonb,
  intake_fields = $liw$[{"type":"section","label":"Your real estate objective","help":"Choose the path that best describes what you want LIW to help you accomplish."},{"key":"transaction_type","type":"radio","label":"What do you need help with?","options":["Buy a home","Sell a property","Rent a home or apartment","Lease commercial space"],"required":true,"span":"full"},{"key":"preferred_areas","type":"text","label":"Preferred neighborhood, borough, or service area","placeholder":"Example: East New York, Cypress Hills, Queens","help":"List more than one area if you are flexible.","span":"full"},{"key":"target_timeline","type":"select","label":"Target timeline","options":["As soon as possible","Within 30 days","1–3 months","3–6 months","6+ months","Just researching"]},{"key":"currently_working_with_agent","type":"radio","label":"Are you currently represented by another real estate agent?","options":["No","Yes","Not sure"],"required":true},{"type":"section","label":"Rental search details","help":"Complete these questions for a residential rental search.","show_when":{"key":"transaction_type","values":["Rent a home or apartment"]}},{"key":"rental_monthly_budget","type":"currency","label":"Maximum monthly rent","placeholder":"2500","show_when":{"key":"transaction_type","values":["Rent a home or apartment"]}},{"key":"bedrooms_needed","type":"select","label":"Bedrooms needed","options":["Studio","1 bedroom","2 bedrooms","3 bedrooms","4+ bedrooms"],"show_when":{"key":"transaction_type","values":["Rent a home or apartment"]}},{"key":"household_size","type":"number","label":"Number of people in household","min":1,"show_when":{"key":"transaction_type","values":["Rent a home or apartment"]}},{"key":"move_in_date","type":"date","label":"Desired move-in date","show_when":{"key":"transaction_type","values":["Rent a home or apartment"]}},{"key":"housing_program","type":"select","label":"Housing assistance or rental program","options":["None","Section 8","CityFHEPS","FHEPS","HASA","Other program"],"required":false,"show_when":{"key":"transaction_type","values":["Rent a home or apartment"]}},{"key":"rental_requirements","type":"checkboxes","label":"Important rental needs","options":["Pet-friendly","Parking","Accessible entrance","Elevator","Near public transportation","Laundry","Outdoor space"],"required":false,"span":"full","show_when":{"key":"transaction_type","values":["Rent a home or apartment"]}},{"type":"section","label":"Home purchase details","help":"Complete these questions if you are preparing to buy.","show_when":{"key":"transaction_type","values":["Buy a home"]}},{"key":"purchase_budget","type":"currency","label":"Maximum purchase budget","placeholder":"650000","show_when":{"key":"transaction_type","values":["Buy a home"]}},{"key":"mortgage_preapproval","type":"select","label":"Mortgage pre-approval status","options":["Pre-approved","Application in progress","Need lender guidance","Cash purchase","Not sure yet"],"show_when":{"key":"transaction_type","values":["Buy a home"]}},{"key":"down_payment_range","type":"select","label":"Estimated down payment","options":["Less than 3%","3%–5%","6%–10%","11%–20%","More than 20%","Not sure"],"required":false,"show_when":{"key":"transaction_type","values":["Buy a home"]}},{"key":"buyer_property_types","type":"checkboxes","label":"Property types you would consider","options":["Single-family","Two-family","Multi-family","Condo","Co-op","Mixed-use","Commercial"],"span":"full","show_when":{"key":"transaction_type","values":["Buy a home"]}},{"key":"buyer_must_haves","type":"textarea","label":"Must-haves and deal-breakers","placeholder":"Bedrooms, parking, condition, school area, accessibility, investment goals…","required":false,"span":"full","show_when":{"key":"transaction_type","values":["Buy a home"]}},{"type":"section","label":"Property sale details","help":"Complete these questions if you want to list or sell property.","show_when":{"key":"transaction_type","values":["Sell a property"]}},{"key":"property_address","type":"text","label":"Property address","autocomplete":"street-address","span":"full","show_when":{"key":"transaction_type","values":["Sell a property"]}},{"key":"seller_property_type","type":"select","label":"Property type","options":["Single-family","Two-family","Multi-family","Condo","Co-op","Commercial","Mixed-use","Land","Other"],"show_when":{"key":"transaction_type","values":["Sell a property"]}},{"key":"property_occupancy","type":"select","label":"Current occupancy","options":["Owner occupied","Tenant occupied","Vacant","Partially occupied"],"show_when":{"key":"transaction_type","values":["Sell a property"]}},{"key":"mortgage_on_property","type":"select","label":"Is there a mortgage or lien on the property?","options":["Mortgage only","No mortgage","Possible lien or judgment","Not sure"],"required":false,"show_when":{"key":"transaction_type","values":["Sell a property"]}},{"key":"desired_listing_date","type":"date","label":"Desired listing date","required":false,"show_when":{"key":"transaction_type","values":["Sell a property"]}},{"key":"property_condition","type":"textarea","label":"Describe the property condition and recent improvements","required":false,"span":"full","show_when":{"key":"transaction_type","values":["Sell a property"]}},{"type":"section","label":"Commercial lease details","help":"Complete these questions for a storefront, office, warehouse, or other business space.","show_when":{"key":"transaction_type","values":["Lease commercial space"]}},{"key":"business_use","type":"text","label":"Intended business use","placeholder":"Example: Daycare, office, salon, retail store","span":"full","show_when":{"key":"transaction_type","values":["Lease commercial space"]}},{"key":"commercial_monthly_budget","type":"currency","label":"Maximum monthly lease budget","show_when":{"key":"transaction_type","values":["Lease commercial space"]}},{"key":"square_feet_needed","type":"text","label":"Approximate square footage needed","placeholder":"Example: 1,200–1,800 sq. ft.","show_when":{"key":"transaction_type","values":["Lease commercial space"]}},{"key":"commercial_requirements","type":"checkboxes","label":"Space requirements","options":["Street-level access","Parking","Kitchen or food use","High electrical capacity","Loading access","Office buildout","ADA accessibility","Near public transportation"],"required":false,"span":"full","show_when":{"key":"transaction_type","values":["Lease commercial space"]}},{"key":"real_estate_notes","type":"textarea","label":"Anything else LIW should know?","required":false,"span":"full"}]$liw$::jsonb,
  updated_at = now()
where code = 'real-estate';

update public.service_catalog set
  intake_heading = 'Tell us about the property and the management support you need.',
  intake_intro = 'LIW uses this information to understand the property size, occupancy, current challenges, and the level of management support requested.',
  subject_placeholder = 'Example: Management support for a four-unit Brooklyn property',
  intake_notice = 'Do not enter tenant Social Security numbers, bank account details, access codes, or other highly sensitive information in this form.',
  document_checklist = $liw$["Property ownership or authorization documents","Current rent roll or lease summary, when available","Open violation or maintenance records, when relevant","Property photos and existing management agreements"]$liw$::jsonb,
  intake_fields = $liw$[{"type":"section","label":"Property and ownership profile"},{"key":"requester_role","type":"radio","label":"Your relationship to the property","options":["Owner","Investor or prospective buyer","Authorized representative","Board or association member"],"span":"full"},{"key":"property_address","type":"text","label":"Property address","autocomplete":"street-address","span":"full"},{"key":"property_type","type":"select","label":"Property type","options":["Single-family rental","Two-family","Multi-family residential","Commercial","Mixed-use","Condo or co-op building","Other"]},{"key":"number_of_units","type":"number","label":"Total number of units","min":1},{"key":"occupied_units","type":"number","label":"Currently occupied units","min":0,"required":false},{"key":"property_status","type":"select","label":"Current property status","options":["Fully occupied","Partially occupied","Vacant","Under renovation","Not yet acquired"]},{"key":"currently_managed","type":"radio","label":"Is another company currently managing the property?","options":["No","Yes","Self-managed"],"span":"full"},{"type":"section","label":"Services requested"},{"key":"management_services","type":"checkboxes","label":"Which services are you interested in?","options":["Full-service property management","Tenant communication","Rent collection support","Maintenance coordination","Vendor coordination","Property inspections","Tenant placement","Lease administration","Violation follow-up","Owner reporting","Consultation only"],"span":"full"},{"key":"current_challenges","type":"checkboxes","label":"Current challenges","options":["Late or unpaid rent","Vacant units","Frequent maintenance issues","Tenant complaints","Vendor problems","Recordkeeping","Violations or notices","After-hours emergencies","No current system","Other"],"required":false,"span":"full"},{"key":"monthly_rent_roll","type":"currency","label":"Approximate total monthly rent roll","required":false},{"key":"desired_start_date","type":"date","label":"Desired management start date","required":false},{"key":"emergency_issue","type":"radio","label":"Is there an urgent property or tenant issue right now?","options":["No","Yes"],"span":"full"},{"key":"urgent_issue_details","type":"textarea","label":"Describe the urgent issue","span":"full","show_when":{"key":"emergency_issue","values":["Yes"]}},{"key":"management_details","type":"textarea","label":"Describe the property, current workflow, and what successful management would look like","span":"full"}]$liw$::jsonb,
  updated_at = now()
where code = 'property-management';

update public.service_catalog set
  intake_heading = 'Tell us which tax return or tax issue you need help with.',
  intake_intro = 'This preliminary intake identifies the return type, tax years, income sources, deadlines, and documents LIW should prepare to review.',
  subject_placeholder = 'Example: 2025 individual tax return with W-2 and 1099 income',
  intake_notice = 'For your protection, do not enter Social Security numbers, full dates of birth, bank routing numbers, or identity-document numbers here. Upload requested tax documents only through the secure portal.',
  document_checklist = $liw$["Government-issued identification","Social Security or ITIN documents through secure upload only","W-2, 1099, K-1, retirement, or unemployment forms","Prior-year return and any IRS or state notices","Business income and expense records, when applicable"]$liw$::jsonb,
  intake_fields = $liw$[{"type":"section","label":"Return type and filing profile"},{"key":"tax_service_needed","type":"radio","label":"What tax service do you need?","options":["Current-year individual return","Prior-year return","Amended return","Self-employed or 1099 return","Business return","Rental property return","Tax notice consultation"],"span":"full"},{"key":"tax_years","type":"checkboxes","label":"Tax year or years involved","options":["2025","2024","2023","2022 or earlier","Multiple years","Not sure"],"span":"full"},{"key":"filing_status","type":"select","label":"Expected filing status","options":["Single","Married filing jointly","Married filing separately","Head of household","Qualifying surviving spouse","Not sure"],"required":false},{"key":"state_residency","type":"text","label":"States lived or worked in during the tax year","placeholder":"Example: New York only","required":false},{"key":"dependents","type":"number","label":"Number of dependents","min":0,"required":false},{"key":"first_time_client","type":"radio","label":"Have you filed with LIW before?","options":["No, first time","Yes"],"span":"full"},{"type":"section","label":"Income and tax documents"},{"key":"income_sources","type":"checkboxes","label":"Income sources to report","options":["W-2 wages","1099 contractor income","Business income","Rental property income","Unemployment","Retirement or pension","Social Security benefits","Investments or cryptocurrency","Alimony","Other income"],"span":"full"},{"key":"business_structure","type":"select","label":"Business structure","options":["Sole proprietor","Single-member LLC","Partnership","S corporation","C corporation","Nonprofit","Not sure"],"show_when":{"key":"tax_service_needed","values":["Business return","Self-employed or 1099 return"]}},{"key":"business_books_ready","type":"select","label":"Are business income and expenses organized?","options":["Yes, complete","Partially organized","Need bookkeeping help","Not applicable"],"required":false,"show_when":{"key":"tax_service_needed","values":["Business return","Self-employed or 1099 return"]}},{"key":"major_tax_changes","type":"checkboxes","label":"Major changes during the year","options":["Marriage or divorce","New child or dependent","Bought or sold a home","Moved to another state","Started or closed a business","Bought or sold investments","Received health-insurance marketplace coverage","None of these"],"required":false,"span":"full"},{"key":"prior_return_available","type":"radio","label":"Do you have a copy of your most recent filed return?","options":["Yes","No","Not sure"],"span":"full"},{"key":"tax_notice_received","type":"radio","label":"Did you receive an IRS or state tax notice?","options":["No","Yes"],"span":"full"},{"key":"notice_deadline","type":"date","label":"Deadline shown on the notice","required":false,"show_when":{"key":"tax_notice_received","values":["Yes"]}},{"key":"notice_summary","type":"textarea","label":"Briefly describe the notice","span":"full","show_when":{"key":"tax_notice_received","values":["Yes"]}},{"key":"tax_questions","type":"textarea","label":"Questions, concerns, or special circumstances","required":false,"span":"full"}]$liw$::jsonb,
  updated_at = now()
where code = 'tax-preparation';

update public.service_catalog set
  intake_heading = 'Tell us what is happening on your credit reports and what you want to accomplish.',
  intake_intro = 'This intake helps LIW prepare for a credit-report review, education session, dispute-support discussion, or goal-based credit plan.',
  subject_placeholder = 'Example: Credit report review before applying for a mortgage',
  intake_notice = 'Do not enter Social Security numbers, full account numbers, passwords, or credit-monitoring login credentials. Credit outcomes and score changes cannot be guaranteed.',
  document_checklist = $liw$["Current credit reports from the bureaus","Identification and proof of address through secure upload only","Collection or creditor correspondence","Prior dispute results, when available","Identity-theft report, when applicable"]$liw$::jsonb,
  intake_fields = $liw$[{"type":"section","label":"Credit goal and current position"},{"key":"credit_goal","type":"radio","label":"Primary reason for contacting LIW","options":["Review my credit reports","Address inaccurate information","Create a credit-building plan","Prepare for a mortgage","Prepare for an auto loan","Prepare for business funding","Debt-validation guidance","General consultation"],"span":"full"},{"key":"goal_timeline","type":"select","label":"When do you hope to reach this goal?","options":["Within 30 days","1–3 months","3–6 months","6–12 months","No fixed deadline"]},{"key":"estimated_score_range","type":"select","label":"Estimated credit-score range","options":["Below 500","500–579","580–619","620–669","670–739","740+","I do not know"]},{"key":"credit_reports_available","type":"radio","label":"Do you have current reports from all three bureaus?","options":["Yes","Some reports","No"],"span":"full"},{"key":"bureaus_involved","type":"checkboxes","label":"Bureaus with items you want reviewed","options":["Experian","Equifax","TransUnion","Not sure"],"required":false,"span":"full"},{"type":"section","label":"Items and history to review"},{"key":"credit_item_types","type":"checkboxes","label":"Types of items affecting your reports","options":["Late payments","Collections","Charge-offs","Medical debt","High credit-card utilization","Hard inquiries","Identity theft or fraud","Incorrect personal information","Closed accounts reporting incorrectly","Public records","Student loans","Other or unknown"],"span":"full"},{"key":"identity_theft","type":"radio","label":"Do you believe identity theft or fraud is involved?","options":["No","Yes","Not sure"],"span":"full"},{"key":"prior_disputes","type":"radio","label":"Have you disputed any items before?","options":["No","Yes","Not sure"],"span":"full"},{"key":"prior_dispute_results","type":"textarea","label":"Describe previous disputes and results","required":false,"span":"full","show_when":{"key":"prior_disputes","values":["Yes"]}},{"key":"upcoming_application","type":"select","label":"Upcoming application","options":["None planned","Mortgage","Rental housing","Auto loan","Credit card","Business funding","Other"],"required":false},{"key":"credit_summary","type":"textarea","label":"Describe the main concerns you want LIW to review","placeholder":"List creditor names or item types, but do not enter full account numbers.","span":"full"},{"key":"credit_expectation","type":"radio","label":"I understand LIW cannot guarantee deletions, score increases, or lender approval.","options":["I understand"],"span":"full"}]$liw$::jsonb,
  updated_at = now()
where code = 'credit-solutions';

update public.service_catalog set
  intake_heading = 'Tell us about the business, funding need, and current financial profile.',
  intake_intro = 'LIW uses this preliminary information to understand possible funding paths and identify records that may be requested during review.',
  subject_placeholder = 'Example: Working-capital request for an established Brooklyn business',
