  document_checklist = $liw$["Business formation documents","Recent business bank statements","Business tax returns or profit-and-loss statement","Government-issued identification through secure upload","Existing loan statements, when applicable"]$liw$::jsonb,
  intake_fields = $liw$[{"type":"section","label":"Business profile"},{"key":"legal_business_name","type":"text","label":"Legal business name","span":"full"},{"key":"dba_name","type":"text","label":"DBA or trade name","required":false},{"key":"entity_type","type":"select","label":"Business structure","options":["Sole proprietor","LLC","Partnership","S corporation","C corporation","Nonprofit","Other"]},{"key":"industry","type":"text","label":"Industry or business activity"},{"key":"state_formed","type":"text","label":"State where the business is registered","required":false},{"key":"time_in_business","type":"select","label":"Time in business","options":["Not yet operating","Less than 6 months","6–12 months","1–2 years","2–5 years","5+ years"]},{"key":"ownership_percentage","type":"number","label":"Your ownership percentage","min":0,"max":100,"required":false},{"key":"business_bank_account","type":"radio","label":"Does the business have a dedicated bank account?","options":["Yes","No","Opening one now"],"span":"full"},{"type":"section","label":"Funding request"},{"key":"funding_amount","type":"currency","label":"Amount of funding requested","placeholder":"50000"},{"key":"funding_timeline","type":"select","label":"When is funding needed?","options":["Immediately","Within 30 days","1–3 months","3–6 months","Exploring options"]},{"key":"funding_purpose","type":"checkboxes","label":"How would the funds be used?","options":["Working capital","Equipment","Inventory","Marketing","Expansion or renovation","Payroll","Debt consolidation","Real estate","Vehicle","Startup costs","Other"],"span":"full"},{"key":"average_monthly_revenue","type":"currency","label":"Average monthly business revenue","placeholder":"15000"},{"key":"estimated_annual_revenue","type":"currency","label":"Estimated annual revenue","required":false},{"key":"business_credit_range","type":"select","label":"Owner’s estimated personal credit range","options":["Below 500","500–579","580–619","620–669","670–739","740+","Do not know"],"required":false},{"key":"existing_business_debt","type":"radio","label":"Does the business currently have loans or cash advances?","options":["No","Yes","Not sure"],"span":"full"},{"key":"existing_debt_balance","type":"currency","label":"Approximate current business debt balance","required":false,"show_when":{"key":"existing_business_debt","values":["Yes"]}},{"key":"bank_statements_ready","type":"select","label":"Recent business bank statements available?","options":["Yes, 6+ months","Yes, 3 months","Only 1–2 months","No"]},{"key":"funding_details","type":"textarea","label":"Describe the business opportunity, use of funds, and any timing concerns","span":"full"},{"key":"funding_acknowledgement","type":"radio","label":"I understand that submitting this intake does not guarantee approval or specific terms.","options":["I understand"],"span":"full"}]$liw$::jsonb,
  updated_at = now()
where code = 'business-loans';

