the audience know or do?","span":"full"},{"key":"required_contact_info","type":"textarea","label":"Contact information that must appear","placeholder":"Phone, email, address, website, social handles…","span":"full"},{"key":"print_or_media_specs","type":"textarea","label":"Sizes, quantities, platforms, or media specifications","required":false,"span":"full"},{"key":"campaign_start_date","type":"date","label":"Desired campaign or distribution date","required":false},{"key":"creative_deadline","type":"date","label":"Final artwork deadline","required":false},{"key":"project_budget","type":"select","label":"Estimated project or advertising budget","options":["Under $250","$250–$499","$500–$999","$1,000–$2,499","$2,500–$4,999","$5,000+","Need a recommendation"],"required":false},{"key":"advertising_notes","type":"textarea","label":"Additional creative direction, references, or campaign details","required":false,"span":"full"}]$liw$::jsonb,
