update public.service_catalog set
  intake_heading = 'Tell us about the frame, damage, and preferred repair method.',
  intake_intro = 'Detailed frame information and clear photos help LIW determine whether inspection, adjustment, part replacement, or specialty repair may be appropriate.',
  subject_placeholder = 'Example: Broken hinge repair for prescription eyeglasses',
